css:
.chat {
  max-width: 420px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
}

.top {
  padding: 12px 16px;
  border-radius: 7px 7px 0 0;
  background: #18181b;
  color: #fafafa;
  font-weight: 600;
}

.messages {
  padding: 12px;
}

.msg {
  margin: 0;
  padding: 8px 12px;
  border-radius: 12px;
  background: #e4e4e7;
}

.msg--me {
  background: #fed7aa;
}

.composer {
  padding: 10px;
  border-top: 1px solid #d4d4d8;
}

.field {
  padding: 8px 10px;
  border: 1px solid #a1a1aa;
  border-radius: 4px;
}

.send {
  padding: 8px 14px;
  border: 0;
  border-radius: 4px;
  background: #f97316;
  color: #fff;
}

