/* ---- Solution ---- */
.chat {
  display: flex;
  flex-direction: column;
  height: 360px;
}

.messages {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.msg {
  max-width: 70%;
  align-self: flex-start;
}

.msg--me {
  align-self: flex-end;
}

.composer {
  display: flex;
  gap: 8px;
}

.field {
  flex: 1;
}
